// Minimal endless runner game
// Canvas element with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 400;

  const player = { x: 50, y: height - 40, w: 20, h: 20, vy: 0, jumpForce: -12, onGround: true };
  const gravity = 0.6;
  const obstacles = [];
  let spawnTimer = 0;
  let gameOver = false;

  const keys = {};
  document.addEventListener('keydown', e => { keys[e.code] = true; if (e.code === 'Space') jump(); });
  document.addEventListener('keyup', e => { keys[e.code] = false; });
  canvas.addEventListener('click', jump);

  function jump() {
    if (player.onGround) {
      player.vy = player.jumpForce;
      player.onGround = false;
    }
  }

  function spawnObstacle() {
    const size = 20;
    obstacles.push({ x: width, y: height - size, w: size, h: size, speed: 6 });
  }

  function update() {
    if (gameOver) return;
    // Player physics
    player.vy += gravity;
    player.y += player.vy;
    if (player.y + player.h >= height) {
      player.y = height - player.h;
      player.vy = 0;
      player.onGround = true;
    }
    // Obstacles
    spawnTimer--;
    if (spawnTimer <= 0) {
      spawnObstacle();
      spawnTimer = 100 + Math.random() * 100;
    }
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= o.speed;
      // Collision
      if (player.x < o.x + o.w && player.x + player.w > o.x &&
          player.y < o.y + o.h && player.y + player.h > o.y) {
        gameOver = true;
      }
      // Remove off‑screen
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Player
    ctx.fillStyle = '#e53935';
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // Obstacles
    ctx.fillStyle = '#212121';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  loop();
})();
